  _Atomic uint32_t head;
  _Atomic uint32_t tail;
  uint64_t slots[CAP];
  _Atomic int state; // 0 empty, 1 has item
} Ring;
```
```javascript
// Enqueue (producer)
while (((head+1)%CAP) == tail) futex_wait(&state,0);
slots[head] = v;
head = (head+1)%CAP;
futex_wake(&state,1);
```
```javascript
// Dequeue (consumer)
while (head == tail) futex_wait(&state,1);
v = slots[tail];
tail = (tail+1)%CAP;
futex_wake(&state,0);
```

